	code := strings.TrimSpace(chiURLParam(r, "code"))
	var request struct {
		Name             *string `json:"name"`
		Description      *string `json:"description"`
		AssignableByUser *bool   `json:"assignableByUser"`
		Enabled          *bool   `json:"enabled"`
	}
	if !decodeJSON(w, r, &request) {
		return
