	if keyscope.Protected(code) && request.AssignableByUser != nil && *request.AssignableByUser {
		writeError(w, http.StatusBadRequest, "scope_protected", "관리자 전용 scope는 개인 할당 가능 상태로 변경할 수 없습니다.")
