name=coalesce($2,name),description=coalesce($3,description),
assignable_by_user=CASE WHEN $7 THEN false ELSE coalesce($4,assignable_by_user) END,
enabled=coalesce($5,enabled),updated_by=$6,updated_at=now() WHERE code=$1`, code, request.Name, request.Description, request.AssignableByUser, request.Enabled, p.ID, keyscope.Protected(code))
